{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table asaya-data-room-487110.maplemonk.nykaa_po_fill_date as SELECT a.*, coalesce(a.po_release_date_1, b.order_Date) as po_release_Date, b.order_date, row_number () over (partition by appt_po_number order by appointment_date) rw, safe_divide(b.quantity, count(1) over (partition by coalesce(a.po_release_date_1, b.order_Date) order by 1)) sales_quantity, safe_divide(b.selling_price, count(1) over (partition by coalesce(a.po_release_date_1, b.order_Date) order by 1)) selling_price, c.zone, \"Nykaa\" as Platform, CASE WHEN MIN(grn_date) OVER (PARTITION BY appt_po_number) IS NULL THEN \'Not Delivered Yet\' WHEN MIN(appointment_date) OVER (PARTITION BY appt_po_number) IS NULL THEN \'Not Delivered Yet\' WHEN DATE_DIFF( MIN(grn_date) OVER (PARTITION BY appt_po_number), MIN(appointment_date) OVER (PARTITION BY appt_po_number), DAY) = 0 THEN \'Same Day Delivery\' WHEN DATE_DIFF( MIN(grn_date) OVER (PARTITION BY appt_po_number), MIN(appointment_date) OVER (PARTITION BY appt_po_number), DAY) = 1 THEN \'Delivered in 2 Days\' WHEN DATE_DIFF( MIN(grn_date) OVER (PARTITION BY appt_po_number), MIN(appointment_date) OVER (PARTITION BY appt_po_number), DAY) = 2 THEN \'Delivered in 3 Days\' ELSE CONCAT(\'Delivered in \', DATE_DIFF( MIN(grn_date) OVER (PARTITION BY appt_po_number), MIN(appointment_date) OVER (PARTITION BY appt_po_number), DAY) , \' Days\') END AS delivery_label, COUNT(appointment_status) OVER (PARTITION BY appt_po_number) AS attempt_label, CASE WHEN MIN(uc_invoice_date) OVER (PARTITION BY po_number) IS NULL THEN \'Invoice Not Done Yet\' WHEN MIN(po_release_date_1) OVER (PARTITION BY po_number) IS NULL THEN \'Invoice Not Done Yet\' WHEN DATE_DIFF( MIN(uc_invoice_date) OVER (PARTITION BY po_number), MIN(po_release_date_1) OVER (PARTITION BY po_number), DAY) = 0 THEN \'Same Day Invoice\' WHEN DATE_DIFF( MIN(uc_invoice_date) OVER (PARTITION BY po_number), MIN(po_release_date_1) OVER (PARTITION BY po_number), DAY) = 1 THEN \'Invoiced in 2 Days\' WHEN DATE_DIFF( MIN(uc_invoice_date) OVER (PARTITION BY po_number), MIN(po_release_date_1) OVER (PARTITION BY po_number), DAY) = 2 THEN \'Invoiced in 3 Days\' ELSE CONCAT(\'Invoiced in \', DATE_DIFF( MIN(uc_invoice_date) OVER (PARTITION BY po_number), MIN(po_release_date_1) OVER (PARTITION BY po_number), DAY) , \' Days\') END AS po_to_invoice_label, CASE WHEN MIN(uc_dispatch_date) OVER (PARTITION BY po_number) IS NULL THEN \'Dispatch Not Done Yet\' WHEN MIN(uc_invoice_date) OVER (PARTITION BY po_number) IS NULL THEN \'Dispatch Not Done Yet\' WHEN DATE_DIFF( MIN(uc_dispatch_date) OVER (PARTITION BY po_number), MIN(uc_invoice_date) OVER (PARTITION BY po_number), DAY) = 0 THEN \'Same Day Dispatch\' WHEN DATE_DIFF( MIN(uc_dispatch_date) OVER (PARTITION BY po_number), MIN(uc_invoice_date) OVER (PARTITION BY po_number), DAY) = 1 THEN \'Dispatched in 2 Days\' WHEN DATE_DIFF( MIN(uc_dispatch_date) OVER (PARTITION BY po_number), MIN(uc_invoice_date) OVER (PARTITION BY po_number), DAY) = 2 THEN \'Dispatched in 3 Days\' ELSE CONCAT(\'Dispatched in \', DATE_DIFF( MIN(uc_dispatch_date) OVER (PARTITION BY po_number), MIN(uc_invoice_date) OVER (PARTITION BY po_number), DAY) , \' Days\') END AS invoice_to_dispatch_label, CASE WHEN MIN(appointment_date) OVER (PARTITION BY po_number) IS NULL THEN \'Appointment Not Booked Yet\' WHEN MIN(uc_dispatch_date) OVER (PARTITION BY po_number) IS NULL THEN \'Appointment Not Booked Yet\' WHEN DATE_DIFF( MIN(appointment_date) OVER (PARTITION BY po_number), MIN(uc_dispatch_date) OVER (PARTITION BY po_number), DAY) = 0 THEN \'Same Day Appointment\' WHEN DATE_DIFF( MIN(appointment_date) OVER (PARTITION BY po_number), MIN(uc_dispatch_date) OVER (PARTITION BY po_number), DAY) = 1 THEN \'Appointment in 2 Days\' WHEN DATE_DIFF( MIN(appointment_date) OVER (PARTITION BY po_number), MIN(uc_dispatch_date) OVER (PARTITION BY po_number), DAY) = 2 THEN \'Appointment in 3 Days\' ELSE CONCAT(\'Appointment in \', DATE_DIFF( MIN(appointment_date) OVER (PARTITION BY po_number), MIN(uc_dispatch_date) OVER (PARTITION BY po_number), DAY), \' Days\') END AS dispatch_to_appointment_label, CASE WHEN MIN(grn_date) OVER (PARTITION BY po_number) IS NULL THEN \'GRN Not Done Yet\' WHEN MIN(po_release_date_1) OVER (PARTITION BY po_number) IS NULL THEN \'GRN Not Done Yet\' WHEN DATE_DIFF( MIN(grn_date) OVER (PARTITION BY po_number), MIN(po_release_date_1) OVER (PARTITION BY po_number), DAY) = 0 THEN \'Same Day GRN\' WHEN DATE_DIFF( MIN(grn_date) OVER (PARTITION BY po_number), MIN(po_release_date_1) OVER (PARTITION BY po_number), DAY) = 1 THEN \'GRN in 2 Days\' WHEN DATE_DIFF( MIN(grn_date) OVER (PARTITION BY po_number), MIN(po_release_date_1) OVER (PARTITION BY po_number), DAY) = 2 THEN \'GRN in 3 Days\' ELSE CONCAT(\'GRN in \', DATE_DIFF( MIN(grn_date) OVER (PARTITION BY po_number), MIN(po_release_date_1) OVER (PARTITION BY po_number), DAY) , \' Days\') END AS po_to_grn_label, CASE WHEN MIN(grn_date) OVER (PARTITION BY po_number) IS NULL THEN \'GRN Not Done Yet\' WHEN MIN(uc_dispatch_date) OVER (PARTITION BY po_number) IS NULL THEN \'GRN Not Done Yet\' WHEN DATE_DIFF( MIN(grn_date) OVER (PARTITION BY po_number), MIN(uc_dispatch_date) OVER (PARTITION BY po_number), DAY) = 0 THEN \'Same Day GRN\' WHEN DATE_DIFF( MIN(grn_date) OVER (PARTITION BY po_number), MIN(uc_dispatch_date) OVER (PARTITION BY po_number), DAY) = 1 THEN \'GRN in 2 Days\' WHEN DATE_DIFF( MIN(grn_date) OVER (PARTITION BY po_number), MIN(uc_dispatch_date) OVER (PARTITION BY po_number), DAY) = 2 THEN \'GRN in 3 Days\' ELSE CONCAT(\'GRN in \', DATE_DIFF( MIN(grn_date) OVER (PARTITION BY po_number), MIN(uc_dispatch_date) OVER (PARTITION BY po_number), DAY) , \' Days\') END AS dispatch_to_grn_label FROM ( (WITH latest_po_snapshot AS ( SELECT po_number, MAX(scraped_at) AS max_scraped_at FROM `asaya-data-room-487110.Maplemonk.nykaa_po_report` GROUP BY po_number ), po_data AS ( SELECT p.po_number, p.vendor_name AS po_vendor_name, p.warehouse_location AS po_warehouse_location, p.seller_name AS po_seller_name, p.po_created_by, p.po_status, SAFE_CAST(p.po_qty AS FLOAT64) AS po_qty, SAFE_CAST(p.po_amount AS FLOAT64) AS po_amount, COALESCE( SAFE.PARSE_DATE(\'%d-%m-%Y\', p.issue_date), SAFE.PARSE_DATE(\'%Y-%m-%d\', p.issue_date) ) AS po_release_date_1 FROM `asaya-data-room-487110.Maplemonk.nykaa_po_report` p JOIN latest_po_snapshot l ON p.po_number = l.po_number AND p.scraped_at = l.max_scraped_at WHERE p.po_number != \'nan\' ), latest_grn_snapshot AS ( SELECT po_number, MAX(scraped_at) AS max_scraped_at FROM `asaya-data-room-487110.Maplemonk.nykaa_grn_report` GROUP BY po_number ), base_grn AS ( SELECT COALESCE( SAFE.PARSE_DATE(\'%d-%m-%Y\', g.grn_date), SAFE.PARSE_DATE(\'%Y-%m-%d\', g.grn_date) ) AS grn_date, g.warehouse_location AS grn_warehouse, g.vendor_name AS grn_vendor_name, g.grn_status, g.grn_number, g.po_number, SUM(SAFE_CAST(g.grn_qty AS FLOAT64)) AS grn_qty, SUM(SAFE_CAST(g.grn_amount AS FLOAT64)) AS grn_amount FROM `asaya-data-room-487110.Maplemonk.nykaa_grn_report` g JOIN latest_grn_snapshot l ON g.po_number = l.po_number AND g.scraped_at = l.max_scraped_at GROUP BY 1, 2, 3, 4, 5, 6 ), po_totals AS ( SELECT po_number, SUM(grn_qty) AS total_grn_qty, SUM(grn_amount) AS total_grn_amount FROM base_grn GROUP BY po_number ), primary_grn AS ( SELECT grn_date, grn_warehouse, grn_vendor_name, grn_status, grn_number, po_number, grn_qty, grn_amount, ROW_NUMBER() OVER ( PARTITION BY po_number ORDER BY grn_qty DESC ) AS rn FROM base_grn ), grn_final AS ( SELECT p.grn_date, p.grn_warehouse, p.grn_vendor_name, p.grn_status, p.grn_number, p.po_number AS grn_po_number, t.total_grn_qty AS grn_qty, t.total_grn_amount AS grn_amount FROM primary_grn p JOIN po_totals t ON p.po_number = t.po_number WHERE p.rn = 1 ), uc_data AS ( SELECT DATE(Order_Date) AS uc_order_date, DATE(invoiceDate) AS uc_invoice_date, DATE(Dispatch_Date) AS uc_dispatch_date, reference_code AS uc_po_number, marketplace AS uc_channel_name, invoice_code AS uc_invoice_code, Warehouse_Name AS uc_facility, shippingPackageStatus AS uc_shippingPackageStatus, order_status AS uc_order_status, SUM(subordeR_quantity) AS uc_sold_qty, SUM(selling_price) AS uc_selling_price FROM `asaya-data-room-487110.Maplemonk.unicommerce_b2b_sales_report_fact_items` WHERE cleaned_channel = \"Nykaa\" AND order_status In (\'COMPLETE\', \"PROCESSING\") AND invoiceDate IS NOT NULL GROUP BY 1, 2, 3, 4, 5, 6, 7, 8, 9 ), uc_final AS ( SELECT uc_order_date, uc_invoice_date, uc_dispatch_date, uc_po_number, uc_channel_name, uc_invoice_code, uc_facility, uc_shippingPackageStatus, uc_order_status, uc_sold_qty, uc_selling_price, ROW_NUMBER() OVER ( PARTITION BY uc_po_number ORDER BY uc_order_date DESC, uc_invoice_date DESC ) AS rn FROM uc_data ), latest_appt_snap AS ( SELECT appointment_id, po, MAX(scraped_at) AS max_scraped_at FROM `asaya-data-room-487110.Maplemonk.nykaa_appointment_po_report` GROUP BY appointment_id, po ), appt_base AS ( SELECT a.po AS appt_po_number, COALESCE( SAFE.PARSE_DATE(\'%d-%m-%Y\', a.appointment_date), SAFE.PARSE_DATE(\'%Y-%m-%d\', a.appointment_date) ) AS appointment_date, a.appointment_id, a.appointment_status, ROW_NUMBER() OVER ( PARTITION BY a.po ORDER BY COALESCE( SAFE.PARSE_DATE(\'%d-%m-%Y\', a.appointment_date), SAFE.PARSE_DATE(\'%Y-%m-%d\', a.appointment_date) ) DESC, CASE a.appointment_status WHEN \'Received\' THEN 1 WHEN \'Partially Received\' THEN 2 WHEN \'Unloaded\' THEN 3 WHEN \'Booking Confirmed\' THEN 4 WHEN \'No Show\' THEN 5 WHEN \'Rejected\' THEN 6 WHEN \'Cancelled\' THEN 7 ELSE 8 END ASC, a.appointment_id DESC ) AS appt_rn FROM `asaya-data-room-487110.Maplemonk.nykaa_appointment_po_report` a JOIN latest_appt_snap l ON a.appointment_id = l.appointment_id AND a.po = l.po AND a.scraped_at = l.max_scraped_at ) SELECT po.po_number, po.po_vendor_name, po.po_warehouse_location, po.po_seller_name, po.po_created_by, po.po_status, po.po_release_date_1, appt.appointment_id, appt.appointment_date, appt.appt_po_number, appt.appointment_status, CASE WHEN appt.appt_po_number IS NOT NULL AND appt.appt_rn != 1 THEN 0 ELSE po.po_qty END AS po_qty, CASE WHEN appt.appt_po_number IS NOT NULL AND appt.appt_rn != 1 THEN 0 ELSE po.po_amount END AS po_amount, grn.grn_date, grn.grn_po_number, grn.grn_warehouse, grn.grn_vendor_name, grn.grn_status, grn.grn_number, CASE WHEN appt.appt_po_number IS NOT NULL AND appt.appt_rn != 1 THEN 0 ELSE grn.grn_qty END AS grn_qty, CASE WHEN appt.appt_po_number IS NOT NULL AND appt.appt_rn != 1 THEN 0 ELSE grn.grn_amount END AS grn_amount, uc.uc_order_date, uc.uc_invoice_date, uc.uc_dispatch_date, uc.uc_po_number, uc.uc_channel_name, uc.uc_invoice_code, uc.uc_facility, uc.uc_shippingPackageStatus, uc.uc_order_status, CASE WHEN appt.appt_po_number IS NOT NULL AND appt.appt_rn != 1 THEN 0 ELSE uc.uc_sold_qty END AS uc_sold_qty, CASE WHEN appt.appt_po_number IS NOT NULL AND appt.appt_rn != 1 THEN 0 ELSE uc.uc_selling_price END AS uc_selling_price FROM po_data po LEFT JOIN grn_final grn ON po.po_number = grn.grn_po_number LEFT JOIN uc_final uc ON po.po_number = uc.uc_po_number AND uc.rn = 1 LEFT JOIN appt_base appt ON po.po_number = appt.appt_po_number ORDER BY po.po_number, appt.appointment_date) ) a full outer join ( select ordeR_Date, sum(quantity) quantity, sum(selling_price) selling_price, from asaya-data-room-487110.Maplemonk.asaya_sales_dashboard WHERE cleaned_channel = \'NYKAA\' AND secondary_order_type = 1 group by 1 ) b on a.po_release_date_1 = b.order_Date left join ( select distinct destination, zone from asaya-data-room-487110.Maplemonk.gs_warehouse_zone_mapping qualify row_number() over (partition by destination order by 1) = 1 ) c on lower(c.destination) = lower(po_warehouse_location)",
                    "transaction": true
